changeSet.sql:
ALTER TABLE nexus.catalog_documents
    ADD COLUMN index_state        TEXT;
ALTER TABLE nexus.catalog_documents
    ADD COLUMN index_content_hash TEXT NOT NULL DEFAULT '';
ALTER TABLE nexus.catalog_documents
    ADD COLUMN index_run_id       TEXT NOT NULL DEFAULT '';
ALTER TABLE nexus.catalog_documents
    ADD COLUMN index_started_at   TEXT NOT NULL DEFAULT '';

rollback.sql:
ALTER TABLE nexus.catalog_documents DROP COLUMN IF EXISTS index_started_at;
ALTER TABLE nexus.catalog_documents DROP COLUMN IF EXISTS index_run_id;
ALTER TABLE nexus.catalog_documents DROP COLUMN IF EXISTS index_content_hash;
ALTER TABLE nexus.catalog_documents DROP COLUMN IF EXISTS index_state;

changeSet.sql:
CREATE INDEX idx_catalog_documents_index_state
    ON nexus.catalog_documents (tenant_id, index_state)
    WHERE index_state <> 'complete';

rollback.sql:
DO $$
BEGIN
    IF to_regprocedure('nexus.manifest_verify_all()') IS NOT NULL THEN
        REVOKE EXECUTE ON FUNCTION nexus.manifest_verify_all() FROM nexus_svc;
    END IF;
    IF to_regprocedure('nexus.manifest_verify(text)') IS NOT NULL THEN
        REVOKE EXECUTE ON FUNCTION nexus.manifest_verify(text) FROM nexus_svc;
    END IF;
END
$$;
